import site from "@/illustrations/generated/site.json";
import { cn } from "@/lib/cn";

// The detailed 2.5D site illustration, generated by `npm run build:illustrations`.
//
// It is a stack of layers painted in order: the static plant as SVG images (rasterised once by
// the browser, so they cost no DOM), and between them the animated AOne layer as inline SVG
// (data lines, devices, the engineer) so CSS can drive it from the `data-step` of an ancestor.
export function SiteVector({ className }: { className?: string }) {
  const [x, y, width, height] = site.viewBox;
  return (
    <div
      className={cn("site-vector relative", className)}
      style={{ aspectRatio: `${width} / ${height}` }}
      role="img"
      aria-label="An isometric plant with a cold room, a machining line, utilities, a dispatch dock, a kitchen block and a power yard. Sensors and cameras connect to an AOne gateway and one dashboard; an alert on a compressor is raised and then cleared by a BluSquad engineer."
    >
      {site.layers.map((layer, index) =>
        layer.kind === "image" ? (
          // eslint-disable-next-line @next/next/no-img-element -- a vector layer: nothing for next/image to optimise
          <img key={index} src={layer.src} alt="" width={width} height={height} loading="lazy" decoding="async" className="absolute inset-0 h-full w-full" />
        ) : (
          <svg key={index} viewBox={`${x} ${y} ${width} ${height}`} aria-hidden="true" className="absolute inset-0 h-full w-full" dangerouslySetInnerHTML={{ __html: layer.markup ?? "" }} />
        ),
      )}
    </div>
  );
}
